PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('guest','maker','admin','support','partner')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(id TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL,physically_validated INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),storage_key TEXT NOT NULL,edits TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS instructions(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),sequence_hash TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress(instruction_id TEXT NOT NULL REFERENCES instructions(id),user_id TEXT NOT NULL REFERENCES users(id),revision INTEGER NOT NULL,confirmed INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(instruction_id,user_id));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,family TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>=0),currency TEXT NOT NULL,profile_id TEXT,stock INTEGER NOT NULL CHECK(stock>=0),credits INTEGER NOT NULL CHECK(credits>=0),development_data INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('pending','paid','cancelled','fulfilled','return_requested','refunded')),total_minor INTEGER NOT NULL CHECK(total_minor>=0),currency TEXT NOT NULL,address TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_lines(order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_minor INTEGER NOT NULL CHECK(unit_price_minor>=0),credits INTEGER NOT NULL CHECK(credits>=0),PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS payments(event_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider TEXT NOT NULL,status TEXT NOT NULL,amount_minor INTEGER NOT NULL,received_at TEXT NOT NULL,payload_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS code_batches(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS codes(hash TEXT PRIMARY KEY,batch_id TEXT REFERENCES code_batches(id),profile_id TEXT NOT NULL,quota INTEGER NOT NULL CHECK(quota>0),expires_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,redeemed_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS redemptions(code_hash TEXT PRIMARY KEY REFERENCES codes(hash),user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credit_ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL,reason TEXT NOT NULL,source TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,sequence_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('reserved','succeeded','failed')),instruction_id TEXT REFERENCES instructions(id),UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS gifts(hash TEXT PRIMARY KEY,buyer_id TEXT NOT NULL REFERENCES users(id),credits INTEGER NOT NULL CHECK(credits>0),redeemed_by TEXT REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fulfillments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),tracking TEXT,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),kind TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('queued','sandbox_recorded','sent','failed')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT);
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),order_id TEXT REFERENCES orders(id),subject TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content(id TEXT PRIMARY KEY,kind TEXT NOT NULL,license TEXT NOT NULL,asset_key TEXT NOT NULL,locale TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,partner_id TEXT REFERENCES users(id),configuration TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS promotions(id TEXT PRIMARY KEY,configuration TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS referrals(id TEXT PRIMARY KEY,creator_id TEXT REFERENCES users(id),campaign_id TEXT REFERENCES campaigns(id));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),instruction_id TEXT REFERENCES instructions(id),consent INTEGER NOT NULL DEFAULT 0,moderation TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS region_configuration(country TEXT PRIMARY KEY,currency TEXT NOT NULL,shipping TEXT NOT NULL,providers TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1,datetime('now'));
